// Hand-written `aws-sdk` (version 2) stub for the flowatlas fixture suite.
//
// Version 2 is one package for every service: a namespace object holding one
// class per service, each method taking its input directly and answering with
// a request whose `promise()` is awaited. Only the document client is here,
// because that is the only version 2 call the fixture makes.

export declare class Request<T> {
  promise(): Promise<T>;
}

export declare namespace DynamoDB {
  interface DeleteItemInput {
    TableName: string;
    Key: Record<string, unknown>;
  }
  class DocumentClient {
    constructor(options?: { region?: string });
    delete(params: DeleteItemInput): Request<unknown>;
  }
}

declare const AWS: {
  DynamoDB: typeof DynamoDB;
};

export default AWS;
